<template><main class="login"><el-card><h1>智能班级管理系统</h1><p class="hint">登录教学管理工作空间</p><el-form label-position="top" @submit.prevent="login"><el-form-item label="账号"><el-input v-model="form.username" placeholder="请输入账号" aria-label="账号" autocomplete="username"/></el-form-item><el-form-item label="密码"><el-input v-model="form.password" type="password" placeholder="请输入密码" aria-label="密码" autocomplete="current-password" show-password/></el-form-item><el-button type="primary" native-type="submit" :loading="loading">登录</el-button></el-form></el-card></main></template><script setup>import {reactive,ref} from 'vue';import {useRouter} from 'vue-router';import {ElMessage} from 'element-plus';import api from '../api';const router=useRouter(),loading=ref(false),form=reactive({username:'',password:''});async function login(){if(loading.value)return;if(!form.username.trim()||!form.password)return ElMessage.warning('请输入账号和密码');loading.value=true;try{const r=await api.post('/auth/login',form);localStorage.token=r.data.data.token;localStorage.user=JSON.stringify(r.data.data.user);router.push('/')}catch(e){ElMessage.error(e.response?.data?.message||e.message||'登录失败')}finally{loading.value=false}}</script><style scoped>.login{min-height:100vh;display:grid;place-items:center;background:#f3f6fb}.el-card{width:min(90vw,420px)}.el-input,.el-button{margin:8px 0;width:100%}h1{font-size:24px;margin-bottom:8px}.hint{text-align:center;margin-bottom:26px}</style>
<style scoped>
.login{min-height:100dvh;background:#eef3f6;padding:32px;grid-template-columns:minmax(300px,520px) minmax(320px,420px);justify-content:center;gap:7vw}.login::before{content:'让班级工作更从容。';font-size:clamp(28px,3.2vw,44px);font-weight:650;letter-spacing:1px;line-height:1.6;color:#294b70;max-width:400px;padding:40px 0 40px 26px;border-left:4px solid #86a69a}.el-card{width:100%;border:1px solid #e0e7ed;border-radius:20px;padding:24px;box-shadow:0 16px 48px #294b700a}h1{font-size:25px;margin-top:4px}.hint{text-align:left;margin:10px 0 30px}.el-button{min-height:44px}.el-input{margin:4px 0}.login :deep(.el-input__wrapper){min-height:44px}.login :deep(.el-form-item){margin-bottom:22px}@media(max-width:760px){.login{grid-template-columns:minmax(0,420px);gap:28px;padding:24px}.login::before{font-size:24px;padding:10px 0 10px 18px;max-width:none;justify-self:start}.el-card{padding:12px}}
</style>
<style scoped>.login::before{font-size:clamp(28px,2.6vw,38px);max-width:none;text-wrap:balance}@media(max-width:760px){.login::before{font-size:24px}}</style>
